+#[test]
+fn hashline_count_salt_rejects_a_stale_duplicate_anchor_and_the_retry_lands() {
+    // `salt = "count"`: a duplicate hashes as `rank/count`, so a third brace
+    // re-hashes all three. Under the default rank salt the stale hash would
+    // instead follow rank 2 to the inserted line 2 and edit the wrong copy.
+    let env = Env::new(
+        "hashline-count",
+        json!({ "steps": [
+            { "call": "read", "args": { "path": "notes.txt" } },
+            { "call": "shell", "args": { "command": "sed -i '2i }' notes.txt" } },
+            { "call": "edit", "args": { "path": "notes.txt", "edits": [ { "op": "set", "anchor": "zv", "text": "end" } ] } },
+            { "call": "read", "args": { "path": "notes.txt" } },
+            { "call": "edit", "args": { "path": "notes.txt", "edits": [ { "op": "set", "anchor": "fh", "text": "end" } ] } },
+            { "text": "done" }
+        ] }),
+    );
+    env.config("[tools]\neditor = \"hashline\"\n\n[tools.hashline]\nanchor = \"hash\"\nsalt = \"count\"\n");
+    std::fs::write(env.work.join("notes.txt"), "}\nalpha\n}\nbeta\n").unwrap();
+    let out = env.run(&["run", "--json", "--no-learn", "close the second block"]);
+    assert!(out.status.success(), "{}", text(&out));
+    let reqs = env.requests();
+    assert_eq!(last_tool_result(&reqs[1]), "wt|}\njk|alpha\nzv|}\nds|beta\n");
+    // The stale anchor names nothing now: the batch is rejected, nothing written.
+    let rejected = last_tool_result(&reqs[3]);
+    assert!(rejected.starts_with("Error: REJECTED: 1 of 1 edit(s)"), "{rejected}");
+    assert!(rejected.contains("ANCHOR_NOT_FOUND") && rejected.contains("no line has hash \"zv\" now"), "{rejected}");
+    // A hash-only rejection carries no window, so the retry re-reads; the
+    // fresh anchors then land on the final brace.
+    assert_eq!(last_tool_result(&reqs[4]), "dn|}\nsc|}\njk|alpha\nfh|}\nds|beta\n");
+    let applied = last_tool_result(&reqs[5]);
+    assert!(applied.starts_with("ok: applied 1 edit(s) to notes.txt: replaced line 4"), "{applied}");
+    assert_eq!(std::fs::read_to_string(env.work.join("notes.txt")).unwrap(), "}\n}\nalpha\nend\nbeta\n");
+    let events: Vec<Value> =
+        String::from_utf8_lossy(&out.stdout).lines().filter_map(|l| serde_json::from_str(l).ok()).collect();
+    let edits: Vec<&Value> = events.iter().filter(|e| e["event"] == "tool_end" && e["name"] == "edit").collect();
+    assert_eq!((edits[0]["ok"].clone(), edits[0]["code"].clone()), (json!(false), json!("ANCHOR_NOT_FOUND")));
+    assert_eq!((edits[1]["ok"].clone(), edits[1]["data"]["status"].clone()), (json!(true), json!("applied")));
+    let manifest = events.iter().find(|e| e["event"] == "manifest").expect("manifest event");
+    assert_eq!(
+        (manifest["hashline"]["anchor"].clone(), manifest["hashline"]["salt"].clone()),
+        (json!("hash"), json!("count"))
+    );
+}
